((SELECT id FROM m), 'Starting Line', 0, 'Chicken Feeder', 'Combination of 5 wings smothered with your choice of wing sauce, mozzarella sticks, buffalo chips, and onion rings.', '$17.00', 17.00, ARRAY[]::text[], 0),
((SELECT id FROM m), 'Starting Line', 0, 'Coop Balls', 'Jalapeño, pepper jack cheese, and chicken breast wrapped in bacon, fried and served with home-made ranch dressing.', '$16.00', 16.00, ARRAY[]::text[], 1),
((SELECT id FROM m), 'Starting Line', 0, 'Chicken Tenders', 'Made from scratch chicken tenders | Add Fries +$3.00', '$12.00', 12.00, ARRAY[]::text[], 2),
((SELECT id FROM m), 'Starting Line', 0, 'Gizzards', 'Golden breaded gizzards served with your choice of any wing sauce.', '$13.00', 13.00, ARRAY[]::text[], 3),
((SELECT id FROM m), 'Starting Line', 0, 'Potato Skins', 'Six piping hot Idaho potato halves smothered with cheddar jack cheese and bacon crumbles, served with sour cream.', '$13.00', 13.00, ARRAY[]::text[], 4),
((SELECT id FROM m), 'Starting Line', 0, 'Buffalo Chips', 'A basket of spicy fried potato chips served with a side of homemade ranch dressing.', '$11.00', 11.00, ARRAY[]::text[], 5),
((SELECT id FROM m), 'Starting Line', 0, 'Cheese Sticks', 'Mozzarella coated with a golden beer batter and fried crisp served with marinara sauce.', '$13.00', 13.00, ARRAY[]::text[], 6),
((SELECT id FROM m), 'Starting Line', 0, 'Poppers', 'Lightly breaded cream cheese-filled jalapeño peppers, deep-fried to a crisp golden brown and served piping hot.', '$14.00', 14.00, ARRAY[]::text[], 7),
((SELECT id FROM m), 'Starting Line', 0, 'Irish Nachos', 'These nachos are made with seasoned waffle fries, and topped with taco beef, shredded lettuce, cheese sauce, pico de gallo, sour cream, and guacamole.', '$17.00', 17.00, ARRAY[]::text[], 8),
((SELECT id FROM m), 'Starting Line', 0, 'The Coop Nachos', 'Our signature nachos! Corn tortilla chips, shredded lettuce, nacho cheese sauce, pico de gallo, sour cream, and guacamole | Your choice of meat: Beef | Chicken | Graziano Sausage | Substitute Grilled Steak +$2.00', '$16.00', 16.00, ARRAY[]::text[], 9),
((SELECT id FROM m), 'Starting Line', 0, 'The Coop Quesadilla', 'Lightly grilled flour tortilla stuffed with three cheeses, served with lettuce, pico de gallo, sour cream, and salsa | Your choice of meat: Beef | Chicken | Graziano Sausage | Substitute Grilled Steak +$2.00', '$16.00', 16.00, ARRAY[]::text[], 10),
((SELECT id FROM m), 'Starting Line', 0, 'Coop Classic Favorites', 'Garlic mushrooms, cheese curds, onion rings, breaded cauliflower, or pickle fries.', 'Choose One $13.00 | Choose Two $18.00 | Choose Three $26.00', 13.00, ARRAY[]::text[], 11),
((SELECT id FROM m), 'Hall of Fame Wings', 1, 'Bone-In Wing', 'Award-winning jumbo wings, fresh, never frozen, marinated and slow-roasted, with your choice of homemade sauce and dressing. Wing sauces: Honey BBQ, Jack Daniels, Parmesan Garlic, Pepper Teriyaki, Jamaican Jerk, Spicy BBQ, Kicked Bourbon, Tropical Heat, Jalapeno Garlic, Buffalo, Buck Nasty. Dry rubs: Sweet Rub, Spicy Rub. Sub all drummies +$2.99 per request; served crispy upon request.', '10 Wings (pick 1 flavor) $18.00 | 20 Wings (pick up to 2 flavors) $35.00 | 40 Wings (pick up to 4 flavors) $60.00', 10, ARRAY[]::text[], 12),
((SELECT id FROM m), 'Hall of Fame Wings', 1, 'Boneless Wing', NULL, 'Half (pick 1 flavor) $14.00 | Full (pick up to 2 flavors) $25.00 | Double (pick up to 4 flavors) $50.00', 1, ARRAY[]::text[], 13),
((SELECT id FROM m), 'Home Run Burgers', 2, 'Hamburger', 'The classic standard, ground beef patty on a bun, keep it simple, or load it up | Add Mushrooms $1.50 | Add Bacon $2.00 | Add Cheese $1.00', '$15.00', 15.00, ARRAY[]::text[], 14),
((SELECT id FROM m), 'Home Run Burgers', 2, 'Patty Melt', 'A fan favorite! Our juicy cooked to order ground chuck served on marble rye bread with grilled onions and American cheese.', '$17.00', 17.00, ARRAY[]::text[], 15),
((SELECT id FROM m), 'Home Run Burgers', 2, 'The Farmer', 'Our half-pound patty covered with a fried egg and topped with two strips of crispy bacon and American cheese.', '$17.00', 17.00, ARRAY[]::text[], 16),
((SELECT id FROM m), 'Home Run Burgers', 2, 'The Middle Child', 'Smothered in our buffalo sauce, with pepperoni slices and pepper jack cheese.', '$17.00', 17.00, ARRAY[]::text[], 17),
((SELECT id FROM m), 'Home Run Burgers', 2, '*Totally "Jack" Burger', 'Our signature jack daniels sauce, sauteed mushrooms and pepper jack cheese.', '$17.00', 17.00, ARRAY[]::text[], 18),
((SELECT id FROM m), 'Home Run Burgers', 2, 'Anders Burger', 'Juicy burger patty, two bacon slices, American cheese, onion strings and our special sauce.', '$17.00', 17.00, ARRAY[]::text[], 19),
((SELECT id FROM m), 'Home Run Burgers', 2, 'Big B Chopped Cheese', 'Signature burger (or buffalo chicken) with gooey cheese and caramelized onions, with a side of special sauce.', '$17.00', 17.00, ARRAY[]::text[], 20),
((SELECT id FROM m), 'The Green', 3, 'Chicken Salad', 'Choose grilled or crispy chicken breast and a wing sauce, with tomatoes and onions, topped with cheddar jack cheese and crunchy corn tortilla strips.', '$15.50', 15.50, ARRAY[]::text[], 21),
((SELECT id FROM m), 'The Green', 3, 'Taco Salad', 'Seasoned ground beef or diced chicken, tomatoes, black olives, cheese, sour cream, guacamole and pico de gallo in a crunchy tortilla bowl | Substitute Grilled Steak +$2.00', '$17.00', 17.00, ARRAY[]::text[], 22),
((SELECT id FROM m), 'The Green', 3, 'Grilled Steak Salad', 'Chunks of tender grilled steak, cheddar, pepper jack & monterrey jack cheeses, pico de gallo and crunchy corn tortilla strips.', '$18.00', 18.00, ARRAY[]::text[], 23),
((SELECT id FROM m), 'Sandwich Board', 4, 'Nashville Hot Chicken Sandwich', 'Flaming-hot hand-breaded chicken thigh meat dipped in cayenne pepper oil and topped with honey drizzle, on a brioche bun with pickles.', '$17.00', 17.00, ARRAY[]::text[], 24),
