((SELECT id FROM m), 'Sandwich Board', 4, 'The Philly', 'Lightly marinated sirloin or chicken grilled with mushrooms, red bell peppers and onions. Topped with provolone cheese.', '$17.00', 17.00, ARRAY[]::text[], 27),
